/* generated child CSS: 06-features/features.card-grid-4/block.css */
/* lab-ui block · features.card-grid-4
   Depends: 00-tokens/tokens.css. Light theme. */

.cards4 {
  padding-block: clamp(4rem, 7vw, 6.5rem);
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family);
}
.cards4 .container {
  max-width: calc(var(--container-width) + var(--container-padding-x) * 2);
  margin-inline: auto;
  padding-inline: var(--container-padding-x);
}

.cards4-top {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr);
  gap: clamp(2rem, 4vw, 4rem);
  align-items: start;
  margin-bottom: clamp(2rem, 4vw, 3.5rem);
}
.cards4-top .eyebrow {
  font-family: var(--font-mono);
  font-size: var(--type-eyebrow-size);
  text-transform: uppercase;
  letter-spacing: var(--type-eyebrow-tracking);
  background: var(--cta-secondary-fill, var(--cta-accent, var(--color-cyan)));
  -webkit-background-clip: text;
          background-clip: text;
  color: transparent;
  margin: 0 0 14px;
}
.cards4-title {
  margin: 0;
  font-weight: var(--type-h2-weight);
  font-size: var(--type-h2-size);
  line-height: var(--type-h2-leading);
  letter-spacing: var(--type-h2-tracking);
  color: var(--color-heading);
}
.cards4-lede { display: grid; gap: 14px; max-width: 44rem; }
.cards4-lede p { margin: 0; font-size: 1rem; line-height: 1.55; color: var(--color-text); }

.cards4-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
}

.cards4-card {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 24px 22px;
  background: var(--color-gray-bg);
  border: 1px solid rgba(0, 0, 0, 0.06);
  border-radius: var(--radius-card);
  transition: border-color 0.2s ease, transform 0.2s ease, box-shadow 0.25s ease;
}
.cards4-card:hover {
  border-color: rgba(0, 0, 0, 0.16);
  transform: translateY(-2px);
  box-shadow: 0 12px 24px -22px rgba(0, 0, 0, 0.25);
}

.cards4-num {
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--cta-secondary-color, var(--color-white));
  align-self: flex-start;
  padding: 3px 9px;
  border-radius: 999px;
  background: var(--cta-secondary-fill, linear-gradient(90deg, #56422D 0%, #494938 100%));
}
.cards4-card-title {
  margin: 0;
  font-size: 1.0625rem;
  font-weight: 600;
  letter-spacing: -0.012em;
  color: var(--color-heading);
}
.cards4-card-p {
  margin: 0;
  font-size: 0.875rem;
  line-height: 1.55;
  color: var(--color-text);
}

@media (max-width: 1180px) {
  .cards4-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 720px) {
  .cards4-top { grid-template-columns: 1fr; }
  .cards4-grid { grid-template-columns: 1fr; }
}
